-- Guest Hub H9 fix 1 (16 Nov 2026, Ahmed — DECISIONS.md 2026-11-16 «Guest Hub H9 fix 1»). Generated by
-- scripts/hub-h9fix-migration.mjs from scripts/hub-h9fix-migration.src.sql and the latest definitions of the functions it
-- edits — never edited once applied (CLAUDE.md §12: a fix is a new migration).
--   1. «قائمة المغادرين» each MORNING (replaces the evening «المغادرة-غدا» upload): reception uploads Nazeel's departures
--      for TODAY by 07:00; the departure check at 09:30; a list uploaded after 09:30 and before 11:00 sends within 5
--      minutes; from 11:00 no departure check that day (its rows still drive the review rules); a review with no answer
--      (10:00 the next day) waits until 11:00 for that morning's list — the same booking number in it is an extension.
--   2. The upload reminders: no list for a branch in use at 07:00 and 08:00 → the staff on shift (nobody on shift: the
--      «مدير الاستقبال» slots), 08:30 → the managers, «التنبيهات» and the daily report's fault line; the free-form line
--      inside the staff member's 24-hour window, else the template hub_upload_reminder once Meta approved it, else the
--      dashboard only; after the upload, a thank-you inside the window. Never after the upload or after 11:00.
--   3. Teaching v2: the teaching combined from the message and its follow-ups, the card it replaces, a link asked for;
--      the quick replies «تمام» / «للفرعين» / «عدّل» / «امسح» and «أسجّلها معلومة للضيوف؟» («سجّلها» / «لا»); an expiry.
-- No unit mode, licence, media switch or global switch changes. No phone number in this file.


-- ───────────────────────────────────────────── 1. teaching v2: the jobs and the follow-ups ─────────────────────────────────────────────
-- the teaching as code combined it (the message and the follow-ups that complete it — prompts.md §9.2), the card it
-- replaces (a follow-up or «عدّل»), and a link asked for (status link)
alter table public.hub_teach_jobs add column body text check (body is null or char_length(body) <= 4000);
alter table public.hub_teach_jobs add column revises uuid references public.hub_knowledge_cards (id) on delete set null;
alter table public.hub_teach_jobs drop constraint hub_teach_jobs_status_check;
alter table public.hub_teach_jobs add constraint hub_teach_jobs_status_check check (status in ('pending', 'running', 'learned', 'asked', 'refused', 'failed', 'link'));
-- one message may now queue a teaching after an earlier job of the same message was answered by a quick reply
comment on column public.hub_teach_jobs.body is 'H9 fix 1: the teaching as code combined it from the message and its follow-ups (prompts.md §9.2); null = the message itself.';

-- what waits for this teacher's next message (24 hours): «أسجّلها معلومة للضيوف؟» (intent), the correction after «عدّل»
-- (edit), a link that was asked for (link). Nothing changes until it is answered.
create table public.hub_teach_followups (
  id uuid primary key default gen_random_uuid(),
  who text not null unique check (who ~ '^(slot|recipient):[0-9a-f-]{36}$'),
  kind text not null check (kind in ('intent', 'edit', 'link')),
  card_id uuid references public.hub_knowledge_cards (id) on delete cascade,
  body text not null check (char_length(body) between 1 and 4000),
  scope text not null check (scope in ('airport-road', 'shafa-road', 'both')),
  link_name text check (link_name is null or char_length(link_name) <= 40),
  channel_id uuid references public.hub_channels (id) on delete set null,
  is_test boolean not null default false,
  created_at timestamptz not null default now()
);
comment on table public.hub_teach_followups is 'Guest Hub H9 fix 1 (16 Nov 2026): what a teacher''s next message completes — the intent question, a correction after «عدّل», a link asked for. 24 hours.';
alter table public.hub_teach_followups enable row level security;
revoke all on table public.hub_teach_followups from public, anon, authenticated;
grant all on table public.hub_teach_followups to service_role;

-- a learned card moved to both branches (the quick reply «للفرعين» — Ahmed only); audited as the teacher
create function internal.hub_learn_rescope(p_card uuid, p_scope text, p_user uuid, p_label text) returns public.hub_knowledge_cards
language plpgsql security definer set search_path = '' as $$
declare
  v_old text := internal.hub_learn_actor(p_user, p_label);
  c public.hub_knowledge_cards;
begin
  update public.hub_knowledge_cards k
     set unit_keys = case when p_scope = 'both' then '{}'::text[]
                          else array(select u.key from public.hub_units u where u.kind = 'branch' and u.branch_slug = p_scope and not u.is_test) end,
         learn_scope = p_scope, updated_by = p_user
   where k.id = p_card and k.status = 'published'
  returning * into c;
  if c.id is not null then
    update public.hub_knowledge_cards k set live = internal.hub_card_snapshot(k) where k.id = c.id returning * into c;
  end if;
  perform internal.hub_learn_actor_end(v_old);
  return c;
end;
$$;

-- the context of a teacher's message (service role — wa-automation's staff path): who may teach, what waits for their next
-- message, their last teaching (2 hours) and the last thing we sent them (a confirmation or the intent question)
create function public.hub_teach_context(p_phone text) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  t jsonb := internal.hub_teacher(p_phone);
  v_who text := t ->> 'who';
  f public.hub_teach_followups;
  c public.hub_knowledge_cards;
begin
  if v_who is null then return jsonb_build_object('teacher', t); end if;
  delete from public.hub_teach_followups x where x.who = v_who and x.created_at < now() - interval '24 hours';
  select * into f from public.hub_teach_followups x where x.who = v_who;
  select * into c from public.hub_knowledge_cards k
   where k.learn_who = v_who and k.learn_kind = 'teach' and k.status = 'published' and k.learned_at > now() - interval '2 hours'
   order by k.learned_at desc limit 1;
  return jsonb_build_object('teacher', t,
    'followup', case when f.id is null then null else jsonb_build_object('id', f.id, 'kind', f.kind, 'card_id', f.card_id, 'body', f.body, 'scope', f.scope, 'link_name', f.link_name) end,
    'last', case when c.id is null then null else jsonb_build_object('id', c.id, 'text_ar', c.text_ar, 'scope', internal.hub_card_scope(c),
                                                                       'minutes', floor(extract(epoch from now() - c.learned_at) / 60)::int) end,
    'last_sent', case when f.kind = 'intent' then jsonb_build_object('kind', 'intent', 'followup_id', f.id)
                      when c.id is not null and exists (select 1 from public.hub_teach_jobs x where x.who = v_who and x.status = 'learned' and x.card_id = c.id)
                        then jsonb_build_object('kind', 'confirm', 'card_id', c.id) end);
end;
$$;

-- ───────────────────────────────────────────── 2. «قائمة المغادرين» each morning (16 Nov 2026, Ahmed) ─────────────────────────────────────────────
-- the list of TODAY is uploaded by 07:00; the departure check at 09:30; a list uploaded after 09:30 and before 11:00 sends
-- within 5 minutes; from 11:00 no departure check that day (its rows still drive the review rules)
create function internal.hub_departure_check_cutoff() returns time
language sql immutable set search_path = '' as $$ select '11:00'::time $$;

-- a reminder that today's list is missing (07:00 and 08:00 the staff on shift — nobody on shift: the «مدير الاستقبال»
-- slots —, 08:30 the managers) and the thank-you after the upload: one row per branch, day, round and slot. mode: session
-- (the 24-hour window with the branch number is open — the model writes it), template (hub_upload_reminder, only once
-- Meta approved it), none (neither: the dashboard entry only). Never a guest, never a text but in hub_staff_messages.
create table public.hub_upload_reminders (
  id uuid primary key default gen_random_uuid(),
  branch_slug text not null references public.branches (slug) on update cascade,
  day date not null,
  round text not null check (round in ('r1', 'r2', 'r3', 'thanks')),
  slot_id uuid references public.hub_staff_slots (id) on delete set null,
  channel_id uuid references public.hub_channels (id) on delete set null,
  mode text check (mode in ('session', 'template', 'none')),
  status text not null default 'queued' check (status in ('queued', 'pending', 'accepted', 'sent', 'delivered', 'read', 'failed', 'skipped', 'test')),
  provider_message_id text,
  error_code text check (error_code is null or char_length(error_code) <= 40),
  cost_usd numeric(12, 6) not null default 0,
  is_test boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (branch_slug, day, round, slot_id, is_test)
);
comment on table public.hub_upload_reminders is 'Guest Hub H9 fix 1 (16 Nov 2026): the reminders that today''s «قائمة المغادرين» is missing (07:00, 08:00, 08:30) and the thank-you after the upload — the slot, the mode, the outcome; never a number or a text.';
create index hub_upload_reminders_queued on public.hub_upload_reminders (created_at) where status = 'queued';
create index hub_upload_reminders_day on public.hub_upload_reminders (branch_slug, day);
create trigger hub_upload_reminders_touch before update on public.hub_upload_reminders for each row execute function internal.stamp();
alter table public.hub_upload_reminders enable row level security;
revoke all on table public.hub_upload_reminders from public, anon, authenticated;
grant all on table public.hub_upload_reminders to service_role;

-- the end of this slot's 24-hour window with this channel (its last message to that number + 24 hours), or null
create function internal.hub_staff_window(p_slot uuid, p_channel uuid, p_now timestamptz default now()) returns timestamptz
language sql stable security definer set search_path = '' as $$
  select max(m.created_at) + interval '24 hours'
    from public.hub_staff_messages m
   where m.direction = 'in' and m.channel_id = p_channel and m.created_at > p_now - interval '24 hours' and m.created_at <= p_now
     and m.who_id in (select s2.id from public.hub_staff_slots s1 join public.hub_staff_slots s2 on s2.phone = s1.phone where s1.id = p_slot
                      union select r.id from public.hub_staff_slots s1 join public.hub_report_recipients r on r.phone = s1.phone where s1.id = p_slot)
$$;

-- a branch uses the list: a switch on, or a list in the last 7 days
create function internal.hub_departures_in_use(p_branch text, p_now timestamptz, p_test boolean) returns boolean
language sql stable security definer set search_path = '' as $$
  select (not coalesce(p_test, false) and exists (select 1 from public.hub_departure_config f where f.branch_slug = p_branch and (f.check_on or f.review_on)))
      or exists (select 1 from public.hub_departure_uploads x where x.branch_slug = p_branch and x.is_test = coalesce(p_test, false) and x.created_at > p_now - interval '7 days')
$$;

-- queue a round's reminders for a branch: r1 / r2 the active staff slots on shift now (nobody on shift → the managers), r3 the
-- managers; thanks: the slots that were really reminded today. Once per round and slot.
create function internal.hub_upload_reminders_queue(p_branch text, p_day date, p_round text, p_now timestamptz, p_test boolean) returns integer
language plpgsql security definer set search_path = '' as $$
declare
  v_channel uuid := internal.hub_branch_channel(p_branch);
  v_n integer := 0;
begin
  if p_round in ('r1', 'r2') then
    insert into public.hub_upload_reminders (branch_slug, day, round, slot_id, channel_id, is_test)
    select p_branch, p_day, p_round, s.id, v_channel, coalesce(p_test, false) from public.hub_staff_slots s
     where s.branch_slug = p_branch and s.active and s.role = 'staff' and internal.hub_slot_covers(s, p_now)
    on conflict do nothing;
    get diagnostics v_n = row_count;
    if v_n = 0 and not exists (select 1 from public.hub_upload_reminders r where r.branch_slug = p_branch and r.day = p_day and r.round = p_round and r.is_test = coalesce(p_test, false)) then
      insert into public.hub_upload_reminders (branch_slug, day, round, slot_id, channel_id, is_test)
      select p_branch, p_day, p_round, s.id, v_channel, coalesce(p_test, false) from public.hub_staff_slots s
       where s.branch_slug = p_branch and s.active and s.role = 'manager'
      on conflict do nothing;
      get diagnostics v_n = row_count;
    end if;
  elsif p_round = 'r3' then
    insert into public.hub_upload_reminders (branch_slug, day, round, slot_id, channel_id, is_test)
    select p_branch, p_day, 'r3', s.id, v_channel, coalesce(p_test, false) from public.hub_staff_slots s
     where s.branch_slug = p_branch and s.active and s.role = 'manager'
    on conflict do nothing;
    get diagnostics v_n = row_count;
  elsif p_round = 'thanks' then
    insert into public.hub_upload_reminders (branch_slug, day, round, slot_id, channel_id, is_test)
    select distinct p_branch, p_day, 'thanks', r.slot_id, v_channel, coalesce(p_test, false) from public.hub_upload_reminders r
     where r.branch_slug = p_branch and r.day = p_day and r.round in ('r1', 'r2', 'r3') and r.is_test = coalesce(p_test, false)
       and r.slot_id is not null and r.status in ('accepted', 'sent', 'delivered', 'read', 'test')
    on conflict do nothing;
    get diagnostics v_n = row_count;
  end if;
  return v_n;
end;
$$;

-- the reminders waiting (service role, wa-automation): each with its window (open → the model writes it; closed → the
-- template, once approved); one whose list was uploaded meanwhile, or whose slot or channel is gone, is skipped
create function public.hub_upload_reminders_claim(p_limit integer default 20, p_test boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  r record;
  v_out jsonb := '[]'::jsonb;
  v_win timestamptz;
begin
  for r in select x.*, ch.address as from_address, ch.waba_id, ch.sending_enabled, s.phone as to_phone, s.active as slot_active, s.name as slot_name, s.role as slot_role
             from public.hub_upload_reminders x left join public.hub_channels ch on ch.id = x.channel_id left join public.hub_staff_slots s on s.id = x.slot_id
            where x.status = 'queued' and x.is_test = coalesce(p_test, false)
            order by x.created_at limit least(greatest(coalesce(p_limit, 20), 1), 50) for update of x skip locked loop
    if r.round <> 'thanks' and exists (select 1 from public.hub_departure_uploads u where u.branch_slug = r.branch_slug and u.departure_date = r.day and u.is_test = r.is_test) then
      update public.hub_upload_reminders set status = 'skipped', error_code = 'uploaded' where id = r.id;
      continue;
    end if;
    if r.to_phone is null or not coalesce(r.slot_active, false) or r.from_address is null then
      update public.hub_upload_reminders set status = 'skipped', error_code = case when r.from_address is null then 'no_channel' else 'no_recipient' end where id = r.id;
      continue;
    end if;
    v_win := internal.hub_staff_window(r.slot_id, r.channel_id, now());
    -- the thank-you only inside the window (never a template)
    if r.round = 'thanks' and v_win is null then
      update public.hub_upload_reminders set status = 'skipped', mode = 'none', error_code = 'no_window' where id = r.id;
      continue;
    end if;
    update public.hub_upload_reminders set status = 'pending' where id = r.id;
    v_out := v_out || jsonb_build_object(
      'id', r.id, 'round', r.round, 'branch', r.branch_slug, 'day', r.day, 'is_test', r.is_test,
      'channel_id', r.channel_id, 'from', r.from_address, 'waba_id', r.waba_id, 'sending_enabled', r.sending_enabled, 'to', r.to_phone,
      'first_name', split_part(btrim(r.slot_name), ' ', 1), 'role', r.slot_role, 'window_expires_at', v_win,
      'link', 'https://admin.armadaresidence.com/?hub_d=' || r.branch_slug,
      'history', (select coalesce(jsonb_agg(jsonb_build_object('author', case when z.direction = 'in' then 'colleague' else 'us' end, 'body', z.body) order by z.created_at), '[]'::jsonb)
                    from (select m.* from public.hub_staff_messages m where m.who_id = r.slot_id and m.channel_id = r.channel_id and m.body is not null
                            and m.created_at > now() - interval '24 hours' order by m.created_at desc limit 6) z),
      'earlier', (select coalesce(jsonb_agg(z.body), '[]'::jsonb) from (select m.body from public.hub_staff_messages m
                    where m.who_id = r.slot_id and m.direction = 'out' and m.body like '%?hub_d=%' order by m.created_at desc limit 6) z),
      'models', (select s.value from public.settings s where s.key = 'hub_models'),
      'prices', (select s.value from public.settings s where s.key = 'hub_model_prices'));
  end loop;
  return v_out;
end;
$$;

-- a reminder's outcome (service role): the mode, YCloud's answer; a free-form text is kept in the colleague chat (30 days)
-- so the next message has its context; the model call into the budget (layer staff_chat)
create function public.hub_upload_reminder_finish(p_id uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  r public.hub_upload_reminders;
  x jsonb;
  v_unit uuid;
  v_cost numeric := 0;
  v_status text := case when p ->> 'status' in ('accepted', 'sent', 'delivered', 'read', 'failed', 'skipped', 'test') then p ->> 'status' else 'failed' end;
begin
  select * into r from public.hub_upload_reminders where id = p_id for update;
  if r.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  select ch.unit_id into v_unit from public.hub_channels ch where ch.id = r.channel_id;
  for x in select * from jsonb_array_elements(coalesce(p -> 'models', '[]'::jsonb)) loop
    if v_unit is not null and coalesce((x ->> 'input_tokens')::bigint, 0) + coalesce((x ->> 'output_tokens')::bigint, 0) > 0 then
      v_cost := v_cost + internal.hub_usage_add(v_unit, 'staff_chat', 'staff', x ->> 'model', (x ->> 'input_tokens')::bigint, (x ->> 'output_tokens')::bigint, r.is_test);
    end if;
  end loop;
  update public.hub_upload_reminders
     set status = v_status, mode = case when p ->> 'mode' in ('session', 'template', 'none') then p ->> 'mode' else mode end,
         provider_message_id = nullif(left(coalesce(p ->> 'provider_id', ''), 200), ''),
         error_code = case when v_status in ('failed', 'skipped') then coalesce(nullif(left(coalesce(p ->> 'error_code', ''), 40), ''), v_status) end,
         cost_usd = cost_usd + v_cost
   where id = r.id;
  if nullif(btrim(coalesce(p ->> 'body', '')), '') is not null and v_status <> 'failed' and r.slot_id is not null then
    insert into public.hub_staff_messages (who_kind, who_id, channel_id, direction, body, provider_message_id, status, is_test)
    values ('staff', r.slot_id, r.channel_id, 'out', left(p ->> 'body', 4096), nullif(left(coalesce(p ->> 'provider_id', ''), 200), ''), v_status, r.is_test)
    on conflict (provider_message_id) do nothing;
  end if;
  return jsonb_build_object('ok', true, 'cost_usd', v_cost);
end;
$$;

-- ?hub_d=<branch> (the reminder's link): the page opens on that branch — nothing to resolve, the branch code is the link
grant execute on function public.hub_teach_context(text), public.hub_upload_reminders_claim(integer, boolean), public.hub_upload_reminder_finish(uuid, jsonb) to service_role;
revoke execute on function public.hub_teach_context(text), public.hub_upload_reminders_claim(integer, boolean), public.hub_upload_reminder_finish(uuid, jsonb) from public, anon, authenticated;


-- ───────────────────────────────────────────── 3. the functions it edits ─────────────────────────────────────────────

create or replace function internal.hub_learn_insert(p_kind text, p_scope text, p_who text, p_name text, p_user uuid, p jsonb, p_replaces text[], p_test boolean)
returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v public.hub_knowledge_cards;
  v_check jsonb;
  v_today date := internal.riyadh_today();
  v_no smallint;
  v_old text;
  v_topics text[];
begin
  v_topics := array(select distinct x from jsonb_array_elements_text(coalesce(p -> 'topic_keys', '[]'::jsonb)) x
                     where exists (select 1 from public.hub_topics t where t.key = x and t.status = 'active' and not t.always_handoff));
  v.key := 'k-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 10);
  v.unit_keys := case when p_scope = 'both' then '{}'::text[]
                      else array(select u.key from public.hub_units u where u.kind = 'branch' and u.branch_slug = p_scope and not u.is_test) end;
  v.topic_keys := v_topics;
  v.title_ar := left(btrim(coalesce(p ->> 'title_ar', '')), 120);
  v.title_en := left(btrim(coalesce(p ->> 'title_en', '')), 120);
  v.text_ar := left(btrim(coalesce(p ->> 'text_ar', '')), 1200);
  v.text_en := left(btrim(coalesce(p ->> 'text_en', '')), 1200);
  v.source := left((case p_kind when 'teach' then 'تعليم واتساب — ' else 'رد الفريق — ' end) || coalesce(nullif(btrim(p_name), ''), 'الفريق') || ' — ' || internal.hub_date_ar(v_today), 300);
  v.source_date := v_today;
  -- H9 fix 1: a fact with a natural end that has not come yet (today up to 400 days); an end in the past is a standing answer
  v.expires_on := case when coalesce(p ->> 'expires_on', '') ~ '^20[0-9]{2}-[0-9]{2}-[0-9]{2}$' and (p ->> 'expires_on')::date between v_today and v_today + 400
                       then (p ->> 'expires_on')::date end;
  v.status := 'draft';
  v_check := internal.hub_card_check(v);
  if jsonb_array_length(v_check -> 'missing') > 0 then return jsonb_build_object('ok', false, 'reason', 'check', 'check', v_check); end if;
  v_old := internal.hub_learn_actor(p_user, case p_kind when 'teach' then 'تعليم واتساب — ' else 'رد الفريق — ' end || coalesce(nullif(btrim(p_name), ''), 'الفريق'));
  perform pg_advisory_xact_lock(hashtext('hub_learn_no'));
  v_no := coalesce((select max(k.learn_no) from public.hub_knowledge_cards k where k.learn_day = v_today), 0) + 1;
  insert into public.hub_knowledge_cards (key, unit_keys, topic_keys, title_ar, title_en, text_ar, text_en, source, source_date, expires_on, verified_by, verified_at, status, sort,
                                          is_test, learn_kind, learn_scope, learn_who, learn_by_name, learn_day, learn_no, learn_short, learned_at, replaces_keys,
                                          published_at, published_by, first_published_at, created_by, updated_by)
  values (v.key, v.unit_keys, v.topic_keys, v.title_ar, v.title_en, v.text_ar, v.text_en, v.source, v.source_date, v.expires_on, p_user, now(), 'draft',
          coalesce((select max(x.sort) + 1 from public.hub_knowledge_cards x), 0), coalesce(p_test, false), p_kind, p_scope, p_who, left(btrim(coalesce(p_name, '')), 80),
          v_today, v_no, nullif(left(btrim(coalesce(p ->> 'short_ar', '')), 80), ''), now(), coalesce(p_replaces, '{}'), now(), p_user, now(), p_user, p_user)
  returning * into v;
  update public.hub_knowledge_cards c set live = internal.hub_card_snapshot(c), status = 'published' where c.id = v.id returning * into v;
  if cardinality(coalesce(p_replaces, '{}')) > 0 then
    update public.hub_knowledge_cards c set status = 'archived', archived_at = now(), archived_by = p_user, updated_by = p_user
     where c.key = any (p_replaces) and c.status <> 'archived';
  end if;
  perform internal.hub_learn_actor_end(v_old);
  return jsonb_build_object('ok', true, 'id', v.id, 'key', v.key, 'n', v_no, 'day', v_today, 'wording', v.text_ar, 'expires_on', v.expires_on);
end;
$$;

create or replace function public.hub_learn_command(p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  t jsonb := internal.hub_teacher(p ->> 'phone');
  v_cmd text := p ->> 'command';
  v_scope text := case when p ->> 'scope' in ('airport-road', 'shafa-road', 'both') then p ->> 'scope' end;
  v_test boolean := coalesce((p ->> 'is_test')::boolean, false);
  v_who text := t ->> 'who';
  v_user uuid := nullif(t ->> 'owner_user', '')::uuid;
  v_label text := 'تعليم واتساب — ' || coalesce(t ->> 'name', '');
  v_verdict text;
  ch public.hub_channels;
  c public.hub_knowledge_cards;
  pd public.hub_teach_pending;
  v_job uuid;
  v_n integer;
  v_r jsonb;
  v_day date;
  -- H9 fix 1: the teaching (combined by code from the message and its follow-ups), the card it replaces, a follow-up
  v_body text := p ->> 'body';
  v_revises uuid := nullif(p ->> 'revises', '')::uuid;
  f public.hub_teach_followups;
  v_id uuid := nullif(p ->> 'id', '')::uuid;
begin
  select * into ch from public.hub_channels where address = p ->> 'channel' order by created_at limit 1;
  if v_cmd in ('yes', 'no') then
    -- only while «أستبدل القديمة؟» waits for this teacher (24 hours); otherwise the colleague chat answers
    select * into pd from public.hub_teach_pending where who = v_who and created_at > now() - interval '24 hours' for update;
    if pd.who is null then return jsonb_build_object('handled', false); end if;
    delete from public.hub_teach_pending where who = pd.who;
    if v_cmd = 'no' then return jsonb_build_object('handled', true, 'line', 'kept'); end if;
    if internal.hub_teach_verdict(t, pd.scope) <> 'ok' then return jsonb_build_object('handled', true, 'line', 'not_allowed'); end if;
    v_r := internal.hub_learn_insert('teach', pd.scope, v_who, t ->> 'name', v_user, pd.candidate, pd.conflicts, pd.is_test or v_test);
    if not coalesce((v_r ->> 'ok')::boolean, false) then return jsonb_build_object('handled', true, 'line', 'failed', 'reason', v_r ->> 'reason'); end if;
    update public.hub_teach_jobs set status = 'learned', card_id = (v_r ->> 'id')::uuid where id = pd.job_id;
    return jsonb_build_object('handled', true, 'line', 'replaced', 'vars', jsonb_build_object('wording', v_r ->> 'wording', 'n', v_r ->> 'n'), 'card_id', v_r ->> 'id');
  end if;
  -- H9 fix 1: the quick replies of a saved card («تمام» / «للفرعين» / «عدّل» / «امسح») — the teacher's own card only
  if v_cmd in ('btn_ok', 'btn_both', 'btn_edit', 'btn_del') then
    if internal.hub_teach_verdict(t, 'airport-road') = 'not_allowed' then return jsonb_build_object('handled', true, 'line', 'not_allowed'); end if;
    select * into c from public.hub_knowledge_cards k where k.id = v_id and k.learn_who = v_who and k.learn_kind = 'teach';
    if c.id is null or c.status <> 'published' then
      return jsonb_build_object('handled', true, 'line', case when v_cmd = 'btn_ok' then 'ok_ack' else 'remove_none' end);
    end if;
    if v_cmd = 'btn_ok' then return jsonb_build_object('handled', true, 'line', 'ok_ack'); end if;
    if v_cmd = 'btn_del' then
      perform internal.hub_learn_archive(c.id, v_user, v_label);
      delete from public.hub_teach_followups x where x.who = v_who and x.card_id = c.id;
      return jsonb_build_object('handled', true, 'line', 'removed', 'vars', jsonb_build_object('wording', c.text_ar), 'card_id', c.id);
    end if;
    if v_cmd = 'btn_edit' then
      insert into public.hub_teach_followups (who, kind, card_id, body, scope, channel_id, is_test)
      values (v_who, 'edit', c.id, c.text_ar, internal.hub_card_scope(c), ch.id, v_test)
      on conflict (who) do update set kind = 'edit', card_id = excluded.card_id, body = excluded.body, scope = excluded.scope, link_name = null,
                                      channel_id = excluded.channel_id, is_test = excluded.is_test, created_at = now();
      return jsonb_build_object('handled', true, 'line', 'edit_ask');
    end if;
    -- «للفرعين»: Ahmed only (a manager teaches his own branch)
    v_verdict := internal.hub_teach_verdict(t, 'both');
    if v_verdict <> 'ok' then
      return jsonb_build_object('handled', true, 'line', v_verdict, 'vars', jsonb_build_object('branch', (select b from unnest(array['airport-road', 'shafa-road']) b
                                                   where not coalesce(t -> 'manager_branches', '[]'::jsonb) @> to_jsonb(b) limit 1)));
    end if;
    c := internal.hub_learn_rescope(c.id, 'both', v_user, v_label);
    return jsonb_build_object('handled', true, 'line', 'saved_both', 'card_id', c.id, 'scope', 'both',
      'vars', jsonb_build_object('wording', c.text_ar, 'expiry', c.expires_on));
  end if;
  -- «أسجّلها معلومة للضيوف؟» asked (once): the teaching waits for «سجّلها» / «لا»
  if v_cmd = 'ask_intent' then
    if internal.hub_teach_verdict(t, coalesce(v_scope, 'airport-road')) = 'not_allowed' then return jsonb_build_object('handled', false); end if;
    if char_length(btrim(coalesce(v_body, ''))) < 3 or v_scope is null then return jsonb_build_object('handled', false); end if;
    insert into public.hub_teach_followups (who, kind, card_id, body, scope, channel_id, is_test)
    values (v_who, 'intent', null, left(btrim(v_body), 4000), v_scope, ch.id, v_test)
    on conflict (who) do update set kind = 'intent', card_id = null, body = excluded.body, scope = excluded.scope, link_name = null,
                                    channel_id = excluded.channel_id, is_test = excluded.is_test, created_at = now()
    returning id into v_id;
    return jsonb_build_object('handled', true, 'line', 'intent_ask', 'followup_id', v_id);
  end if;
  if v_cmd in ('intent_yes', 'intent_no') then
    select * into f from public.hub_teach_followups x where x.who = v_who and x.kind = 'intent' and (v_id is null or x.id = v_id) and x.created_at > now() - interval '24 hours';
    delete from public.hub_teach_followups x where x.who = v_who and x.kind = 'intent';
    if v_cmd = 'intent_no' then return jsonb_build_object('handled', true, 'line', 'intent_no'); end if;
    if f.id is null then return jsonb_build_object('handled', true, 'line', 'failed', 'reason', 'no_followup'); end if;
    v_cmd := 'teach';
    v_body := f.body;
    v_scope := f.scope;
  end if;
  -- a correction after «عدّل» or a link that was asked for: that follow-up is answered by this teaching
  if v_cmd = 'teach' and nullif(p ->> 'followup', '') is not null then
    delete from public.hub_teach_followups x where x.who = v_who and x.id = (p ->> 'followup')::uuid;
  end if;
  if v_cmd = 'offer' then
    -- «عرض:» from Ahmed: offers are added from «العروض» (the same offer feeds the site and the booking price)
    if not coalesce((t ->> 'owner')::boolean, false) then return jsonb_build_object('handled', false); end if;
    return jsonb_build_object('handled', true, 'line', 'offer');
  end if;
  if v_cmd not in ('teach', 'remove_last', 'remove_n') then return jsonb_build_object('handled', false); end if;
  if internal.hub_teach_verdict(t, 'airport-road') = 'not_allowed' then return jsonb_build_object('handled', true, 'line', 'not_allowed'); end if;
  if v_cmd = 'teach' then
    if not internal.hub_learn_on('teach') then return jsonb_build_object('handled', true, 'line', 'teach_off'); end if;
    if v_scope is null then raise exception 'hub_learn_scope' using errcode = '22023'; end if;
    v_verdict := internal.hub_teach_verdict(t, v_scope);
    if v_verdict <> 'ok' then
      return jsonb_build_object('handled', true, 'line', v_verdict,
        'vars', jsonb_build_object('branch', case when v_scope = 'both' then (select b from unnest(array['airport-road', 'shafa-road']) b
                                                   where not coalesce(t -> 'manager_branches', '[]'::jsonb) @> to_jsonb(b) limit 1) else v_scope end));
    end if;
    if char_length(btrim(coalesce(v_body, ''))) < 3 then return jsonb_build_object('handled', true, 'line', 'empty'); end if;
    -- the card a follow-up replaces must be the teacher's own (else a new card)
    if v_revises is not null and not exists (select 1 from public.hub_knowledge_cards k where k.id = v_revises and k.learn_who = v_who and k.status = 'published') then
      v_revises := null;
    end if;
    if ch.id is null then return jsonb_build_object('handled', true, 'line', 'failed', 'reason', 'no_channel'); end if;
    insert into public.hub_teach_jobs (staff_message_id, channel_id, unit_id, who, scope, is_test, body, revises)
    values ((p ->> 'message_id')::uuid, ch.id, ch.unit_id, v_who, v_scope, v_test, left(btrim(v_body), 4000), v_revises)
    on conflict (staff_message_id) do nothing
    returning id into v_job;
    if v_job is null then return jsonb_build_object('handled', true, 'queued', false, 'reason', 'duplicate'); end if;
    if not v_test then perform internal.hub_agent_post('sweep'); end if;
    return jsonb_build_object('handled', true, 'queued', true, 'job_id', v_job);
  end if;
  if v_cmd = 'remove_last' then
    -- the teacher's latest teaching (24 hours), as long as nothing newer was taught by them
    select * into c from public.hub_knowledge_cards k where k.learn_who = v_who and k.learn_kind = 'teach' and k.learned_at > now() - interval '24 hours'
     order by k.learned_at desc limit 1;
    if c.id is null or c.status = 'archived' then return jsonb_build_object('handled', true, 'line', 'remove_none'); end if;
    perform internal.hub_learn_archive(c.id, v_user, v_label);
    return jsonb_build_object('handled', true, 'line', 'removed', 'vars', jsonb_build_object('wording', c.text_ar), 'card_id', c.id);
  end if;
  -- «امسح N»: the number of the latest daily report's line (the day it covers), else today's, else yesterday's
  v_n := nullif(p ->> 'n', '')::integer;
  if v_n is null or v_n < 1 then return jsonb_build_object('handled', true, 'line', 'remove_n_none', 'vars', jsonb_build_object('n', coalesce(v_n, 0))); end if;
  for v_day in select d from (select (select max(r.day) from public.hub_daily_reports r) as d, 1 as o union all select internal.riyadh_today(), 2
                               union all select internal.riyadh_today() - 1, 3) x where d is not null order by o loop
    select * into c from public.hub_knowledge_cards k where k.learn_day = v_day and k.learn_no = v_n and k.is_test = v_test limit 1;
    exit when c.id is not null;
  end loop;
  if c.id is null then return jsonb_build_object('handled', true, 'line', 'remove_n_none', 'vars', jsonb_build_object('n', v_n)); end if;
  if internal.hub_teach_verdict(t, internal.hub_card_scope(c)) <> 'ok' then return jsonb_build_object('handled', true, 'line', 'remove_n_other', 'vars', jsonb_build_object('n', v_n)); end if;
  perform internal.hub_learn_archive(c.id, v_user, v_label);
  return jsonb_build_object('handled', true, 'line', 'removed_n', 'vars', jsonb_build_object('n', v_n, 'wording', c.text_ar), 'card_id', c.id);
end;
$$;

create or replace function public.hub_teach_claim(p_limit integer default 3) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  b jsonb := internal.hub_budget_state();
  v_ids uuid[];
  v_out jsonb;
begin
  if coalesce((b ->> 'capped')::boolean, false) or coalesce((b ->> 'unset')::boolean, false) then return jsonb_build_object('jobs', '[]'::jsonb, 'reason', 'budget_cap'); end if;
  update public.hub_teach_jobs set status = case when attempts >= 2 then 'failed' else 'pending' end, reason = case when attempts >= 2 then 'stuck' end
   where status = 'running' and claimed_at < now() - interval '4 minutes';
  with picked as (select j.id from public.hub_teach_jobs j where j.status = 'pending' order by j.created_at limit least(greatest(coalesce(p_limit, 3), 1), 10) for update skip locked),
  upd as (update public.hub_teach_jobs j set status = 'running', claimed_at = now(), attempts = attempts + 1 from picked where j.id = picked.id returning j.id)
  select coalesce(array_agg(upd.id), '{}') into v_ids from upd;
  select coalesce(jsonb_agg(jsonb_build_object(
           'job_id', j.id, 'scope', j.scope, 'who', j.who, 'is_test', j.is_test, 'message_id', m.id, 'text', coalesce(j.body, m.body),
           -- H9 fix 1: the card this teaching replaces (a follow-up or «عدّل»)
           'revises', (select jsonb_build_object('key', k.key, 'text', k.text_ar) from public.hub_knowledge_cards k where k.id = j.revises), 'sent_at', m.created_at,
           'from', ch.address,
           'to', coalesce((select r.phone from public.hub_report_recipients r where 'recipient:' || r.id = j.who), (select s.phone from public.hub_staff_slots s where 'slot:' || s.id = j.who)),
           'teacher', internal.hub_teacher(coalesce((select r.phone from public.hub_report_recipients r where 'recipient:' || r.id = j.who),
                                                    (select s.phone from public.hub_staff_slots s where 'slot:' || s.id = j.who))))
           order by j.created_at), '[]'::jsonb)
    into v_out
    from public.hub_teach_jobs j join public.hub_staff_messages m on m.id = j.staff_message_id left join public.hub_channels ch on ch.id = j.channel_id
   where j.id = any (v_ids);
  return jsonb_build_object('jobs', v_out, 'topics', internal.hub_learn_topics(), 'cards', internal.hub_learn_cards(), 'today', internal.riyadh_today(),
    'forbidden', to_jsonb(internal.hub_forbidden_terms()), 'known_phones', to_jsonb(internal.hub_known_phones()),
    'models', (select s.value from public.settings s where s.key = 'hub_models'));
end;
$$;

create or replace function public.hub_teach_finish(p_job uuid, p jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  j public.hub_teach_jobs;
  m jsonb;
  t jsonb;
  v_cost numeric := 0;
  v_status text := case when p ->> 'status' in ('learned', 'ask', 'refused', 'failed', 'link') then p ->> 'status' else 'failed' end;
  v_conflicts text[];
  v_r jsonb;
  v_old text;
  v_phone text;
  -- H9 fix 1: the teacher's own recent cards a follow-up replaces
  v_own text[] := '{}';
begin
  select * into j from public.hub_teach_jobs where id = p_job for update;
  if j.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  if j.status <> 'running' then return jsonb_build_object('ok', false, 'reason', 'not_running'); end if;
  for m in select * from jsonb_array_elements(coalesce(p -> 'models', '[]'::jsonb)) loop
    if j.unit_id is not null and coalesce((m ->> 'input_tokens')::bigint, 0) + coalesce((m ->> 'output_tokens')::bigint, 0) > 0 then
      v_cost := v_cost + internal.hub_usage_add(j.unit_id, 'draft_card', 'staff', m ->> 'model', (m ->> 'input_tokens')::bigint, (m ->> 'output_tokens')::bigint, j.is_test);
    end if;
  end loop;
  v_phone := coalesce((select r.phone from public.hub_report_recipients r where 'recipient:' || r.id = j.who), (select s.phone from public.hub_staff_slots s where 'slot:' || s.id = j.who));
  t := internal.hub_teacher(v_phone);
  -- the teacher may still teach this scope (a slot changed since): checked again
  if v_status in ('learned', 'ask') and internal.hub_teach_verdict(t, j.scope) <> 'ok' then
    update public.hub_teach_jobs set status = 'refused', reason = 'not_allowed', cost_usd = cost_usd + v_cost, finished_at = now() where id = j.id;
    return jsonb_build_object('ok', true, 'line', 'not_allowed');
  end if;
  if v_status = 'ask' then
    v_conflicts := array(select distinct x from jsonb_array_elements_text(coalesce(p -> 'conflicts', '[]'::jsonb)) x
                          where exists (select 1 from public.hub_knowledge_cards k where k.key = x and k.status = 'published' and k.id is distinct from j.revises));
    if cardinality(v_conflicts) = 0 then v_status := 'learned'; end if;
    -- H9 fix 1: a contradiction only with the teacher's OWN card of the last 2 hours is a follow-up — the new card replaces
    -- it, never «أستبدل القديمة؟» (Ahmed sent the same teaching twice on 16 Nov 2026)
    if v_status = 'ask' and not exists (select 1 from public.hub_knowledge_cards k where k.key = any (v_conflicts)
                                         and not coalesce(k.learn_who = j.who and k.learn_kind = 'teach' and k.learned_at > now() - interval '2 hours', false)) then
      v_own := v_conflicts;
      v_status := 'learned';
    end if;
  end if;
  -- H9 fix 1: the teaching asks for a link the content does not hold — asked for, never invented; the next message completes it
  if v_status = 'link' then
    insert into public.hub_teach_followups (who, kind, card_id, body, scope, link_name, channel_id, is_test)
    values (j.who, 'link', j.revises, left(coalesce(j.body, (select m2.body from public.hub_staff_messages m2 where m2.id = j.staff_message_id), ''), 4000), j.scope,
            left(btrim(coalesce(p ->> 'name', '')), 40), j.channel_id, j.is_test)
    on conflict (who) do update set kind = 'link', card_id = excluded.card_id, body = excluded.body, scope = excluded.scope, link_name = excluded.link_name,
                                    channel_id = excluded.channel_id, is_test = excluded.is_test, created_at = now();
    update public.hub_teach_jobs set status = 'link', cost_usd = cost_usd + v_cost, finished_at = now() where id = j.id;
    return jsonb_build_object('ok', true, 'line', 'link_ask', 'vars', jsonb_build_object('name', left(btrim(coalesce(p ->> 'name', '')), 40)));
  end if;
  if v_status = 'ask' then
    -- a reception manager never replaces a card of both branches or of the other branch (Ahmed's)
    if not coalesce((t ->> 'owner')::boolean, false)
       and exists (select 1 from public.hub_knowledge_cards k where k.key = any (v_conflicts) and internal.hub_teach_verdict(t, internal.hub_card_scope(k)) <> 'ok') then
      update public.hub_teach_jobs set status = 'refused', reason = 'conflict_shared', cost_usd = cost_usd + v_cost, finished_at = now() where id = j.id;
      return jsonb_build_object('ok', true, 'line', 'conflict_shared',
        'vars', jsonb_build_object('old', (select k.text_ar from public.hub_knowledge_cards k where k.key = any (v_conflicts) order by k.sort limit 1)));
    end if;
    insert into public.hub_teach_pending (who, job_id, channel_id, scope, candidate, conflicts, is_test)
    values (j.who, j.id, j.channel_id, j.scope, coalesce(p -> 'card', '{}'::jsonb), v_conflicts, j.is_test)
    on conflict (who) do update set job_id = excluded.job_id, channel_id = excluded.channel_id, scope = excluded.scope, candidate = excluded.candidate,
                                    conflicts = excluded.conflicts, is_test = excluded.is_test, created_at = now();
    update public.hub_teach_jobs set status = 'asked', cost_usd = cost_usd + v_cost, finished_at = now() where id = j.id;
    return jsonb_build_object('ok', true, 'line', 'ask_replace',
      'vars', jsonb_build_object('wording', p #>> '{card,text_ar}', 'old', (select k.text_ar from public.hub_knowledge_cards k where k.key = any (v_conflicts) order by k.sort limit 1)));
  end if;
  if v_status = 'learned' then
    v_r := internal.hub_learn_insert('teach', j.scope, j.who, t ->> 'name', nullif(t ->> 'owner_user', '')::uuid, coalesce(p -> 'card', '{}'::jsonb),
                                     -- H9 fix 1: a follow-up or «عدّل» replaces the card it completes
                                     coalesce((select array_agg(k.key) from public.hub_knowledge_cards k where k.id = j.revises and k.status <> 'archived'), '{}') || v_own, j.is_test);
    if not coalesce((v_r ->> 'ok')::boolean, false) then
      update public.hub_teach_jobs set status = 'failed', reason = 'check', cost_usd = cost_usd + v_cost, finished_at = now() where id = j.id;
      return jsonb_build_object('ok', true, 'line', 'failed', 'check', v_r -> 'check');
    end if;
    update public.hub_teach_jobs set status = 'learned', card_id = (v_r ->> 'id')::uuid, cost_usd = cost_usd + v_cost, finished_at = now() where id = j.id;
    return jsonb_build_object('ok', true, 'line', case when j.revises is not null or cardinality(v_own) > 0 then 'revised' when j.scope = 'both' then 'saved_both' else 'saved' end,
      'vars', jsonb_build_object('wording', v_r ->> 'wording', 'n', v_r ->> 'n', 'branch', j.scope, 'expiry', v_r ->> 'expires_on'),
      'card_id', v_r ->> 'id', 'scope', j.scope, 'owner', coalesce((t ->> 'owner')::boolean, false));
  end if;
  update public.hub_teach_jobs set status = v_status, reason = case when p ->> 'reason' ~ '^[a-z_]{2,40}$' then p ->> 'reason' end, cost_usd = cost_usd + v_cost, finished_at = now()
   where id = j.id;
  return jsonb_build_object('ok', true, 'line', null);
end;
$$;

create or replace function public.hub_departures_tick(p_now timestamptz default now(), p_test boolean default false) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_l timestamp := p_now at time zone 'Asia/Riyadh';
  v_today date := (p_now at time zone 'Asia/Riyadh')::date;
  v_time time := (p_now at time zone 'Asia/Riyadh')::time;
  d record;
  v_code text;
  v_checks integer := 0;
  v_reviews integer := 0;
  v_dry integer := 0;
  v_skipped integer := 0;
  v_gone integer := 0;
  v_missing integer := 0;
  v_rem integer := 0;
  b text;
  v_unit uuid;
begin
  perform set_config('app.actor', 'scheduler', true);
  -- the site's 10:00 review tick takes the same lock: never two review requests for one stay
  perform pg_advisory_xact_lock(hashtext('armada_stay_review'));
  -- retention: 30 days after the departure date
  delete from public.hub_departures where departure_date < v_today - 30;
  get diagnostics v_gone = row_count;
  delete from public.hub_departure_uploads where departure_date < v_today - 30;
  -- the departure checks of today from 09:30 (a missed day is never sent later)
  for d in select x.*, coalesce(f.check_on, false) as sw, g.hub_blocked_at as blocked
             from public.hub_departures x left join public.hub_departure_config f on f.branch_slug = x.branch_slug
             left join lateral (select p.hub_blocked_at from public.guest_profiles p where p.phone = x.phone and p.merged_into is null order by p.created_at limit 1) g on true
            where x.is_test = coalesce(p_test, false) and x.check_state = 'scheduled'
              and (x.departure_date < v_today or (x.departure_date = v_today and v_time >= time '09:30'))
            for update of x skip locked loop
    v_code := case
      when d.excluded_at is not null then 'excluded'
      when d.answer = 'extend' then 'extended'
      -- H9 fix 1: from 11:00 (a list uploaded late, or a missed clock) no departure check that day
      when d.departure_date < v_today or v_time >= internal.hub_departure_check_cutoff() then 'late'
      when internal.hub_staff_excluded(d.phone) then 'staff_number'
      when d.blocked is not null then 'blocked'
      when not d.sw then 'switch_off' end;
    update public.hub_departures
       set check_state = case when v_code is null then 'queued' when v_code = 'switch_off' then 'dry_run' when v_code in ('excluded', 'extended') then 'cancelled' else 'skipped' end,
           check_code = v_code, check_at = case when v_code is null or v_code = 'switch_off' then p_now else check_at end
     where id = d.id;
    if v_code is null then v_checks := v_checks + 1; elsif v_code = 'switch_off' then v_dry := v_dry + 1; else v_skipped := v_skipped + 1; end if;
  end loop;
  -- a check held back by the limit past the check-out time: too late — skipped (and counted in the daily report)
  update public.hub_departures set check_state = 'skipped', check_code = 'limit_late'
   where is_test = coalesce(p_test, false) and check_state = 'queued' and (departure_date < v_today or v_time >= internal.hub_departure_check_cutoff());
  -- the review requests due
  for d in select x.*, coalesce(f.review_on, false) as sw, g.hub_blocked_at as blocked, g.opted as opted
             from public.hub_departures x left join public.hub_departure_config f on f.branch_slug = x.branch_slug
             left join lateral (select p.hub_blocked_at, internal.wa_opted_out(p) as opted from public.guest_profiles p
                                 where p.phone = x.phone and p.merged_into is null order by p.created_at limit 1) g on true
            where x.is_test = coalesce(p_test, false) and x.review_state = 'scheduled' and x.review_due_at <= p_now
            for update of x skip locked loop
    -- H9 fix 1: a review with no answer (10:00 the next day) waits until 11:00 for that morning's list of its branch — the
    -- same booking number in it moves the guest (an extension) and reschedules the review
    if d.answer is null and v_today = d.departure_date + 1 and v_time < internal.hub_departure_check_cutoff()
       and not exists (select 1 from public.hub_departure_uploads u where u.branch_slug = d.branch_slug and u.departure_date = v_today and u.is_test = d.is_test) then
      continue;
    end if;
    v_code := case
      when d.excluded_at is not null then 'excluded'
      when d.answer = 'extend' then 'extended'
      when internal.hub_staff_excluded(d.phone) then 'staff_number'
      when d.blocked is not null then 'blocked'
      when coalesce(d.opted, false) then 'opted_out'
      -- more than two days late (the clock was down): never sent
      when d.review_due_at < p_now - interval '48 hours' then 'late'
      else internal.hub_review_taken(d.phone, d.branch_slug, d.departure_date, p_now, d.id) end;
    if v_code is null and not d.sw then v_code := 'switch_off'; end if;
    update public.hub_departures
       set review_state = case when v_code is null then 'queued' when v_code = 'switch_off' then 'dry_run' when v_code in ('excluded', 'extended') then 'cancelled' else 'skipped' end,
           review_code = v_code, review_at = case when v_code is null or v_code = 'switch_off' then p_now else review_at end
     where id = d.id;
    if v_code is null then v_reviews := v_reviews + 1; elsif v_code = 'switch_off' then v_dry := v_dry + 1; else v_skipped := v_skipped + 1; end if;
  end loop;
  -- a review held back by the limit for more than two days: skipped
  update public.hub_departures set review_state = 'skipped', review_code = 'limit_late'
   where is_test = coalesce(p_test, false) and review_state = 'queued' and review_deferred_at is not null and review_due_at < p_now - interval '48 hours';
  -- H9 fix 1 (16 Nov 2026): the list of TODAY by 07:00 — no list for a branch in use: 07:00 and 08:00 a reminder to the
  -- staff on shift (nobody on shift: the «مدير الاستقبال» slots), 08:30 the managers, «التنبيهات» and the daily report's
  -- fault line; none after 11:00 or once the list is uploaded (replaces the 23:00 alert for tomorrow's evening list)
  foreach b in array array['airport-road', 'shafa-road'] loop
    if v_time >= time '07:00' and v_time < internal.hub_departure_check_cutoff() and internal.hub_departures_in_use(b, p_now, p_test)
       and not exists (select 1 from public.hub_departure_uploads x where x.branch_slug = b and x.departure_date = v_today and x.is_test = coalesce(p_test, false)) then
      if v_time < time '08:00' then v_rem := v_rem + internal.hub_upload_reminders_queue(b, v_today, 'r1', p_now, p_test);
      elsif v_time < time '08:30' then v_rem := v_rem + internal.hub_upload_reminders_queue(b, v_today, 'r2', p_now, p_test);
      else
        v_rem := v_rem + internal.hub_upload_reminders_queue(b, v_today, 'r3', p_now, p_test);
        select u.id into v_unit from public.hub_units u where u.kind = 'branch' and u.branch_slug = b limit 1;
        insert into public.hub_alerts (kind, unit_id, payload, is_test)
        values ('departures_missing', v_unit, jsonb_build_object('date', v_today, 'branch', b), coalesce(p_test, false))
        on conflict do nothing;
        if found then v_missing := v_missing + 1; end if;
      end if;
    end if;
  end loop;
  if v_rem > 0 and not coalesce(p_test, false) then perform internal.hub_kick_staff_sender(); end if;
  -- the shared limit near its end: the «حد الإرسال المشترك» alert from 80 % (the reserve begins there)
  if not coalesce(p_test, false) then
    declare s jsonb := internal.hub_limit_state(p_now);
    begin
      if (s ->> 'used')::int >= (s ->> 'limit')::int - (s ->> 'reserve')::int then
        insert into public.hub_alerts (kind, unit_id, payload)
        values ('portfolio_pct', null, jsonb_build_object('used', (s ->> 'used')::int, 'limit', (s ->> 'limit')::int, 'at', p_now))
        on conflict do nothing;
      end if;
    end;
  end if;
  if v_checks + v_reviews > 0 then perform internal.wa_kick(); end if;
  return jsonb_build_object('ok', true, 'checks', v_checks, 'reviews', v_reviews, 'dry_run', v_dry, 'skipped', v_skipped, 'deleted', v_gone, 'missing', v_missing, 'reminders', v_rem,
                            'local', v_l);
end;
$$;

create or replace function public.hub_departures_overview() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare v_today date := internal.riyadh_today();
begin
  if not internal.can('departures', 'view') then raise exception 'forbidden' using errcode = '42501'; end if;
  return jsonb_build_object('today', v_today, 'system_admin', internal.is_system_admin(), 'can_edit', internal.can('departures', 'edit'),
    'branches', (select coalesce(jsonb_agg(jsonb_build_object(
        'branch', f.branch_slug, 'check_on', f.check_on, 'review_on', f.review_on,
        'last_upload', (select jsonb_build_object('date', x.departure_date, 'at', x.created_at, 'kept', x.kept) from public.hub_departure_uploads x
                         where x.branch_slug = f.branch_slug and not x.is_test order by x.created_at desc limit 1),
        -- H9 fix 1: the list of TODAY (uploaded each morning by 07:00) and today's reminders
        'today_uploaded', exists (select 1 from public.hub_departure_uploads x where x.branch_slug = f.branch_slug and x.departure_date = v_today and not x.is_test),
        'tomorrow_uploaded', exists (select 1 from public.hub_departure_uploads x where x.branch_slug = f.branch_slug and x.departure_date = v_today + 1 and not x.is_test),
        'reminders', (select coalesce(jsonb_agg(jsonb_build_object('round', r.round, 'name', s.name, 'mode', r.mode, 'status', r.status, 'code', r.error_code, 'at', r.updated_at)
                                               order by r.created_at), '[]'::jsonb)
                        from public.hub_upload_reminders r left join public.hub_staff_slots s on s.id = r.slot_id
                       where r.branch_slug = f.branch_slug and r.day = v_today and not r.is_test),
        'today', (select jsonb_build_object('rows', count(*), 'sent', count(*) filter (where d.check_state in ('accepted', 'sent', 'delivered', 'read')),
                                            'leave', count(*) filter (where d.answer = 'leave'), 'extend', count(*) filter (where d.answer = 'extend'))
                    from public.hub_departures d where d.branch_slug = f.branch_slug and d.departure_date = v_today and not d.is_test))
        order by f.branch_slug), '[]'::jsonb)
      from public.hub_departure_config f where internal.can_branch(f.branch_slug)));
end;
$$;

create or replace function internal.hub_departure_view(d public.hub_departures, f public.hub_departure_config) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'id', d.id, 'branch', d.branch_slug, 'ref', d.nazeel_ref, 'first_name', d.first_name, 'phone', internal.hub_mask_phone(d.phone), 'language', d.language,
    'date', d.departure_date, 'cycle', d.cycle, 'excluded', d.excluded_at is not null, 'answer', d.answer, 'answer_via', d.answer_via, 'answer_at', d.answer_at,
    'check', jsonb_build_object('state', d.check_state, 'code', d.check_code, 'at', d.check_at, 'deferred', d.check_deferred_at is not null,
                                -- H9 fix 1: 09:30, or the upload's time when it came between 09:30 and 11:00; none from 11:00
                                'planned', (select case when z.at < ((d.departure_date)::timestamp + internal.hub_departure_check_cutoff()) at time zone 'Asia/Riyadh' then z.at end
                                              from (select greatest(((d.departure_date)::timestamp + time '09:30') at time zone 'Asia/Riyadh',
                                                                    coalesce((select u.created_at from public.hub_departure_uploads u where u.id = d.upload_id), d.created_at)) as at) z),
                                'cutoff', ((d.departure_date)::timestamp + internal.hub_departure_check_cutoff()) at time zone 'Asia/Riyadh',
                                'switch', coalesce(f.check_on, false)),
    'review', jsonb_build_object('state', d.review_state, 'code', d.review_code, 'at', d.review_at, 'due', d.review_due_at, 'deferred', d.review_deferred_at is not null,
                                 'switch', coalesce(f.review_on, false)),
    -- «استبعاد» until something is sent; «تمديد» until the review request is sent
    'can_exclude', d.check_state in ('scheduled', 'dry_run', 'cancelled', 'skipped') and d.review_state not in ('pending', 'accepted', 'sent', 'delivered', 'read'),
    'can_extend', d.review_state not in ('pending', 'accepted', 'sent', 'delivered', 'read') and (d.answer is null or d.answer_via = 'staff'),
    'updated_at', d.updated_at)
$$;

create or replace function public.hub_departures_upload(p_branch text, p_date date, p_rows jsonb, p_skipped jsonb default '{}'::jsonb, p_dry_run boolean default true) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_today date := internal.riyadh_today();
  v_upload uuid;
  r jsonb;
  v_phone text;
  v_ref text;
  v_name text;
  v_keep jsonb := '[]'::jsonb;
  v_skip jsonb := jsonb_build_object('no_phone', jsonb_build_object('count', 0, 'names', '[]'::jsonb), 'duplicate', jsonb_build_object('count', 0, 'names', '[]'::jsonb),
                                     'staff', jsonb_build_object('count', 0, 'names', '[]'::jsonb), 'bad_phone', jsonb_build_object('count', 0, 'names', '[]'::jsonb),
                                     'bad_ref', jsonb_build_object('count', 0, 'names', '[]'::jsonb));
  v_dups text[];
  v_moved integer := 0;
  v_same integer := 0;
  v_new integer := 0;
  v_older integer := 0;
  v_removed integer := 0;
  v_reason text;
  d public.hub_departures;
  v_counts jsonb;
begin
  if not internal.can('departures', 'edit') or not internal.can_branch(p_branch) then raise exception 'forbidden' using errcode = '42501'; end if;
  if p_branch not in ('airport-road', 'shafa-road') then raise exception 'hub_departures_branch' using errcode = '22023'; end if;
  if p_date is null or p_date < v_today or p_date > v_today + 7 then raise exception 'hub_departures_date' using errcode = '22023'; end if;
  if coalesce(jsonb_typeof(p_rows), '') <> 'array' or jsonb_array_length(p_rows) > 600 then raise exception 'hub_departures_rows' using errcode = '22023'; end if;
  -- the rows the browser skipped for having no phone: the count and the first names only
  if jsonb_typeof(p_skipped -> 'no_phone') = 'array' then
    v_skip := jsonb_set(v_skip, '{no_phone}', jsonb_build_object('count', jsonb_array_length(p_skipped -> 'no_phone'),
                        'names', (select coalesce(jsonb_agg(left(btrim(x), 40)), '[]'::jsonb) from jsonb_array_elements_text(p_skipped -> 'no_phone') x)));
  end if;
  -- a phone on two different booking numbers of the file
  select coalesce(array_agg(p), '{}') into v_dups from (
    select e ->> 'phone' as p from jsonb_array_elements(p_rows) e group by 1 having count(distinct e ->> 'ref') > 1) z;
  for r in select distinct on (e ->> 'ref', e ->> 'phone') e from jsonb_array_elements(p_rows) e loop
    v_phone := btrim(coalesce(r ->> 'phone', ''));
    v_ref := btrim(coalesce(r ->> 'ref', ''));
    v_name := left(btrim(split_part(btrim(coalesce(r ->> 'first_name', '')), ' ', 1)), 40);
    v_reason := case
      when v_phone !~ '^\+[1-9][0-9]{7,14}$' then 'bad_phone'
      when v_ref !~ '^[A-Za-z0-9/_-]{1,40}$' then 'bad_ref'
      when v_phone = any (v_dups) then 'duplicate'
      when internal.hub_staff_lookup(v_phone) is not null then 'staff' end;
    if v_name = '' then v_name := case when v_reason is null then null else '—' end; end if;
    if v_reason is null and v_name is null then v_reason := 'bad_ref'; v_name := '—'; end if;
    if v_reason is not null then
      v_skip := jsonb_set(v_skip, array[v_reason], jsonb_build_object('count', (v_skip -> v_reason ->> 'count')::int + 1,
                          'names', (v_skip -> v_reason -> 'names') || to_jsonb(coalesce(v_name, '—'))));
      continue;
    end if;
    v_keep := v_keep || jsonb_build_object('phone', v_phone, 'ref', v_ref, 'first_name', v_name, 'language', internal.hub_phone_language(v_phone));
  end loop;
  if not p_dry_run then
    perform set_config('app.actor', coalesce(auth.uid()::text, 'departures'), true);
    insert into public.hub_departure_uploads (branch_slug, departure_date, kept, skipped, uploaded_by)
    values (p_branch, p_date, jsonb_array_length(v_keep),
            (select jsonb_object_agg(k, (v_skip -> k ->> 'count')::int) from jsonb_object_keys(v_skip) k), auth.uid())
    returning id into v_upload;
    for r in select * from jsonb_array_elements(v_keep) loop
      select * into d from public.hub_departures x where x.branch_slug = p_branch and x.nazeel_ref = r ->> 'ref' and not x.is_test for update;
      if d.id is null then
        insert into public.hub_departures (branch_slug, nazeel_ref, phone, first_name, language, departure_date, upload_id, review_due_at)
        values (p_branch, r ->> 'ref', r ->> 'phone', r ->> 'first_name', r ->> 'language', p_date, v_upload,
                ((p_date + 1)::timestamp + time '10:00') at time zone 'Asia/Riyadh');
        v_new := v_new + 1;
      elsif d.departure_date = p_date then
        -- the same list again: the phone and the name refreshed, the states kept
        update public.hub_departures set phone = r ->> 'phone', first_name = r ->> 'first_name', language = r ->> 'language', upload_id = v_upload
         where id = d.id;
        v_same := v_same + 1;
      elsif d.departure_date < p_date then
        -- an extension: the guest moves to the new date; what was scheduled for the old date is cancelled; the cycle restarts
        -- (a review already sent stays sent — once per stay)
        update public.hub_departures
           set phone = r ->> 'phone', first_name = r ->> 'first_name', language = r ->> 'language', departure_date = p_date, upload_id = v_upload,
               cycle = least(cycle + 1, 60), excluded_at = null, excluded_by = null, answer = null, answer_via = null, answer_at = null, answer_by = null,
               check_state = 'scheduled', check_code = null, check_at = null, check_ycloud_id = null, check_deferred_at = null,
               review_state = case when review_state in ('accepted', 'sent', 'delivered', 'read') then review_state else 'scheduled' end,
               review_code = case when review_state in ('accepted', 'sent', 'delivered', 'read') then review_code end,
               review_due_at = case when review_state in ('accepted', 'sent', 'delivered', 'read') then review_due_at
                                    else ((p_date + 1)::timestamp + time '10:00') at time zone 'Asia/Riyadh' end,
               review_deferred_at = null
         where id = d.id;
        v_moved := v_moved + 1;
      else
        -- an older list uploaded after a newer one: nothing changes
        v_older := v_older + 1;
      end if;
    end loop;
    -- the same branch and date uploaded again: a guest no longer in the list, with nothing sent yet, is removed
    delete from public.hub_departures x
     where x.branch_slug = p_branch and x.departure_date = p_date and not x.is_test and x.upload_id is distinct from v_upload
       and x.check_state in ('scheduled', 'dry_run', 'cancelled', 'skipped') and x.review_state in ('none', 'scheduled', 'dry_run', 'cancelled', 'skipped')
       and not exists (select 1 from jsonb_array_elements(v_keep) k where k ->> 'ref' = x.nazeel_ref);
    get diagnostics v_removed = row_count;
    update public.hub_departure_uploads set moved = v_moved, removed = v_removed where id = v_upload;
    -- the missing-upload alert of this branch and night is answered
    update public.hub_alerts a set acknowledged_at = now()
     where a.kind = 'departures_missing' and a.acknowledged_at is null and not a.is_test
       and a.unit_id = (select u.id from public.hub_units u where u.kind = 'branch' and u.branch_slug = p_branch limit 1)
       and (a.payload ->> 'date')::date <= p_date;
    -- H9 fix 1: today's list uploaded — no more reminders today; a thank-you to whoever was reminded (inside the window)
    if p_date = v_today and internal.hub_upload_reminders_queue(p_branch, p_date, 'thanks', now(), false) > 0 then
      perform internal.hub_kick_staff_sender();
    end if;
  end if;
  v_counts := jsonb_build_object('kept', jsonb_array_length(v_keep), 'new', v_new, 'same', v_same, 'moved', v_moved, 'older', v_older, 'removed', v_removed);
  return jsonb_build_object('ok', true, 'dry_run', p_dry_run, 'branch', p_branch, 'date', p_date, 'upload_id', v_upload, 'counts', v_counts,
    'kept_names', (select coalesce(jsonb_agg(k ->> 'first_name'), '[]'::jsonb) from jsonb_array_elements(v_keep) k),
    'languages', jsonb_build_object('ar', (select count(*) from jsonb_array_elements(v_keep) k where k ->> 'language' = 'ar'),
                                    'en', (select count(*) from jsonb_array_elements(v_keep) k where k ->> 'language' = 'en')),
    'skipped', v_skip);
end;
$$;

create or replace function internal.hub_limit_state(p_now timestamptz default now()) returns jsonb
language sql stable security definer set search_path = '' as $$
  select jsonb_build_object(
    'limit', l.lim, 'reserve', ceil(l.lim * 0.2)::integer, 'used', cardinality(internal.hub_limit_recent(p_now)),
    'checks', (select count(distinct d.phone) from public.hub_departures d join public.hub_departure_config f on f.branch_slug = d.branch_slug
                where not d.is_test and f.check_on and d.departure_date = (p_now at time zone 'Asia/Riyadh')::date
                  and (p_now at time zone 'Asia/Riyadh')::time < internal.hub_departure_check_cutoff()
                  and d.check_state in ('scheduled', 'queued') and d.excluded_at is null and d.answer is null)
              + (select count(*) from public.whatsapp_messages w where not w.is_test and w.status = 'queued' and w.template = 'arrival_reminder'),
    'reviews', (select count(distinct d.phone) from public.hub_departures d join public.hub_departure_config f on f.branch_slug = d.branch_slug
                 where not d.is_test and f.review_on and d.review_state in ('scheduled', 'queued') and d.review_due_at <= p_now + interval '24 hours'
                   and d.excluded_at is null and d.answer is distinct from 'extend')
               + (select count(*) from public.whatsapp_messages w where not w.is_test and w.status = 'queued' and w.template = 'stay_review'))
  from (select internal.hub_portfolio_limit() as lim) l
$$;

create or replace function internal.hub_limit_recent(p_now timestamptz default now()) returns text[]
language sql stable security definer set search_path = '' as $$
  select coalesce(array_agg(distinct x.phone), '{}') from (
    select r.phone from public.whatsapp_messages w join public.reservations r on r.id = w.reservation_id
     where not w.is_test and w.status in ('pending', 'accepted', 'sent', 'delivered', 'read') and w.created_at > p_now - interval '24 hours' and w.created_at <= p_now
    union all
    select g.phone from public.eyab_messages e join public.guest_profiles g on g.id = e.profile_id
     where not e.is_test and e.template in ('eyab_welcome', 'eyab_offer') and e.status in ('pending', 'accepted', 'sent', 'delivered', 'read')
       and e.updated_at > p_now - interval '24 hours' and e.created_at <= p_now
    union all
    select g.phone from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.guest_profiles g on g.id = c.guest_profile_id
     where not m.is_test and m.direction = 'out' and m.kind = 'template' and m.status in ('accepted', 'sent', 'delivered', 'read')
       and m.sent_at > p_now - interval '24 hours' and m.sent_at <= p_now
    union all
    select coalesce(sl.phone, rr.phone) from public.hub_staff_sends s
      left join public.hub_staff_slots sl on sl.id = s.slot_id left join public.hub_report_recipients rr on rr.id = s.recipient_id
     where not s.is_test and s.status in ('pending', 'accepted', 'sent', 'delivered', 'read') and s.updated_at > p_now - interval '24 hours' and s.created_at <= p_now
    union all
    select d.phone from public.hub_departures d
     where not d.is_test and ((d.check_state in ('pending', 'accepted', 'sent', 'delivered', 'read') and d.check_at > p_now - interval '24 hours' and d.check_at <= p_now)
                           or (d.review_state in ('pending', 'accepted', 'sent', 'delivered', 'read') and d.review_at > p_now - interval '24 hours' and d.review_at <= p_now))
    union all
    -- H9 fix 1: the upload reminders sent as a template
    select s.phone from public.hub_upload_reminders u join public.hub_staff_slots s on s.id = u.slot_id
     where not u.is_test and u.mode = 'template' and u.status in ('pending', 'accepted', 'sent', 'delivered', 'read') and u.updated_at > p_now - interval '24 hours' and u.created_at <= p_now
  ) x where x.phone is not null
$$;

create or replace function internal.hub_report_data(p_day date, p_to timestamptz default null) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_from timestamptz := (p_day::timestamp at time zone 'Asia/Riyadh');
  v_to timestamptz := coalesce(p_to, ((p_day + 1)::timestamp at time zone 'Asia/Riyadh'));
  v_branches jsonb := '{}'::jsonb;
  b text;
  v jsonb;
begin
  foreach b in array array['airport-road', 'shafa-road'] loop
    with conv as (
           select distinct c.id from public.hub_conversations c join public.hub_units u on u.id = c.unit_id join public.hub_messages m on m.conversation_id = c.id
            where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.author = 'guest' and m.sent_at >= v_from and m.sent_at < v_to),
         ho as (select h.* from public.hub_handoffs h where h.branch_slug = b and not h.is_test and h.created_at >= v_from and h.created_at < v_to),
         sends as (select s.* from public.hub_staff_sends s join ho on ho.id = s.handoff_id)
    select jsonb_build_object(
      'conversations', (select count(*) from conv),
      'handed', (select count(distinct ho.conversation_id) from ho),
      'assistant', (select count(*) from conv where not exists (select 1 from ho where ho.conversation_id = conv.id)
                       and exists (select 1 from public.hub_messages m where m.conversation_id = conv.id and m.author = 'assistant' and m.direction = 'out'
                                     and m.status in ('accepted', 'sent', 'delivered', 'read') and m.sent_at >= v_from and m.sent_at < v_to)),
      'reply_avg_min', (select round(avg(extract(epoch from (ho.first_reply_at - ho.created_at)) / 60.0))::integer from ho where ho.first_reply_at is not null),
      'replied', (select count(*) from ho where ho.first_reply_at is not null),
      'bookings', (select count(*) from public.reservations r where r.branch = b and r.booking_source = 'assistant_whatsapp' and not r.is_test
                     and r.created_at >= v_from and r.created_at < v_to),
      'reviews', (select count(*) from public.whatsapp_messages w where w.branch = b and w.template = 'stay_review' and not w.is_test
                    and w.status in ('accepted', 'sent', 'delivered', 'read') and w.created_at >= v_from and w.created_at < v_to)
                 -- H9: and the review requests of «قائمة المغادرين»
                 + (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test
                      and d.review_state in ('accepted', 'sent', 'delivered', 'read') and d.review_at >= v_from and d.review_at < v_to),
      'unanswered', (select count(*) from public.hub_unanswered q join public.hub_units u on u.id = q.unit_id
                       where u.branch_slug = b and not q.is_test and q.created_at >= v_from and q.created_at < v_to),
      'model_failures', (select count(*) from public.hub_turns t join public.hub_units u on u.id = t.unit_id
                           where u.branch_slug = b and not t.is_test and t.status = 'failed' and t.created_at >= v_from and t.created_at < v_to),
      'send_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                          where u.branch_slug = b and not c.is_test and m.direction = 'out' and m.status = 'failed' and m.created_at >= v_from and m.created_at < v_to)
                       + (select count(*) from sends where sends.status = 'failed'),
      -- H7: the voice notes and images that failed (never a cap: it has its own email)
      'voice_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                           where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.kind = 'audio'
                             and m.media_status in ('failed_download', 'failed_transcribe', 'empty', 'unknown_language') and m.created_at >= v_from and m.created_at < v_to),
      'image_failures', (select count(*) from public.hub_messages m join public.hub_conversations c on c.id = m.conversation_id join public.hub_units u on u.id = c.unit_id
                           where u.branch_slug = b and not c.is_test and m.direction = 'in' and m.kind = 'image'
                             and m.media_status in ('failed_download', 'failed_vision') and m.created_at >= v_from and m.created_at < v_to),
      -- 15 Nov 2026: the staff alerts of the branch's hand-offs refused or failed (never silent)
      'staff_refused', (select count(*) from sends where sends.status in ('failed', 'skipped') and coalesce(sends.error_code, '') <> 'qa'),
      'alerts_sent', (select count(*) from sends where sends.status in ('accepted', 'sent', 'delivered', 'read')),
      'alerts_delivered', (select count(*) from sends where sends.status in ('delivered', 'read')),
      'alerts_read', (select count(*) from sends where sends.status = 'read'),
      'escalated', (select count(*) from ho where ho.escalated_at is not null),
      'opened', (select count(*) from ho where ho.opened_at is not null),
      'opened_link', (select count(*) from ho where ho.opened_via = 'link'),
      'email_only', (select count(*) from ho where ho.status = 'email_only'),
      'reasons', (select coalesce(jsonb_object_agg(z.reason, z.n), '{}'::jsonb) from (select coalesce(ho.reason, 'handoff') as reason, count(*) as n from ho group by 1) z),
      -- H9 «الخروج أو التمديد»: the day's departures of the list — the checks sent, «خروج», «تمديد», no answer
      'dep_on', exists (select 1 from public.hub_departure_config f where f.branch_slug = b and (f.check_on or f.review_on))
                or exists (select 1 from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day),
      'dep_rows', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day),
      'dep_sent', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day
                     and d.check_state in ('accepted', 'sent', 'delivered', 'read')),
      'dep_leave', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.answer = 'leave'),
      'dep_extend', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.answer = 'extend'),
      'dep_none', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.answer is null
                     and d.check_state in ('accepted', 'sent', 'delivered', 'read')),
      'dep_dry', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day and d.check_state = 'dry_run'),
      'dep_late', (select count(*) from public.hub_departures d where d.branch_slug = b and not d.is_test and d.departure_date = p_day
                     and d.check_state = 'skipped' and d.check_code in ('late', 'limit_late')),
      -- H9 fix 1: that day's morning list was not uploaded by 08:30 (a branch in use) — the 08:30 reminder's fault line
      'dep_missing', coalesce(p_to, now()) >= ((p_day)::timestamp + time '08:30') at time zone 'Asia/Riyadh'
                     and (exists (select 1 from public.hub_departure_config f where f.branch_slug = b and (f.check_on or f.review_on))
                          or exists (select 1 from public.hub_departure_uploads x where x.branch_slug = b and not x.is_test and x.created_at >= v_from - interval '7 days' and x.created_at < v_to))
                     and not exists (select 1 from public.hub_departure_uploads x where x.branch_slug = b and not x.is_test and x.departure_date = p_day
                                       and x.created_at < ((p_day)::timestamp + time '08:30') at time zone 'Asia/Riyadh')
    ) into v;
    v_branches := v_branches || jsonb_build_object(b, v);
  end loop;
  return jsonb_build_object('day', p_day, 'partial', p_to is not null, 'until', v_to, 'branches', v_branches,
    -- the daily and test reports refused or failed (they belong to no hand-off)
    'reports_refused', (select count(*) from public.hub_staff_sends s where s.kind in ('report', 'report_test') and s.status in ('failed', 'skipped')
                          and coalesce(s.error_code, '') <> 'qa' and not s.is_test and s.created_at >= v_from and s.created_at < v_to),
    -- H7b: the cards published from the dashboard (the learned ones are listed below)
    'cards', (select count(*) from public.hub_knowledge_cards k where not k.is_test and k.learn_kind is null and k.published_at >= v_from and k.published_at < v_to),
    -- H7b: the facts learned that day (teaching and staff replies), numbered for «امسح N» — still active; and what needs Ahmed's decision
    'learned', (select coalesce(jsonb_agg(jsonb_build_object('n', k.learn_no, 'short', coalesce(k.learn_short, k.title_ar), 'branch', k.learn_scope, 'kind', k.learn_kind,
                                                            'by', k.learn_by_name) order by k.learn_no), '[]'::jsonb)
                  from public.hub_knowledge_cards k where not k.is_test and k.learn_day = p_day and k.learn_no is not null and k.status <> 'archived' and k.learned_at <= v_to),
    'decisions', (select count(*) from public.hub_card_jobs j where not j.is_test and j.decision is not null and j.finished_at >= v_from and j.finished_at <= v_to),
    'budget_alerts', (select count(*) from public.hub_alerts a where a.kind in ('budget_pct', 'budget_cap', 'api_credit') and not a.is_test and a.created_at >= v_from and a.created_at < v_to),
    -- H9: the sends held back by the shared limit that day (kept and tried again — never dropped silently)
    'limit_deferred', (select count(*) from public.whatsapp_messages w where not w.is_test and w.deferred_at >= v_from and w.deferred_at < v_to)
                    + (select count(*) from public.eyab_messages e where not e.is_test and e.deferred_at >= v_from and e.deferred_at < v_to)
                    + (select count(*) from public.hub_departures d where not d.is_test and ((d.check_deferred_at >= v_from and d.check_deferred_at < v_to)
                                                                                         or (d.review_deferred_at >= v_from and d.review_deferred_at < v_to))),
    'built_at', now());
end;
$$;

